function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aiLogic || {};

  let currentProducts = [];
  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    // 期間バリデーション（業務ロジック使用）
    if (validateComparisonPeriod) {
      const validation = validateComparisonPeriod(startDate, endDate);
      if (!validation.valid) {
        showError(validation.message);
        return false;
      }
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (!stores) return;

      const select = container.querySelector('#select-store');
      if (!select) return;

      select.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        select.appendChild(option);
      });
    } catch (error) {
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    try {
      const keyword = container.querySelector('#input-search')?.value.trim() || '';
      const category = container.querySelector('#select-category')?.value || '';

      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) return;

      let filtered = products.filter(product => product.有効フラグ && product.AI予測対象フラグ);

      // 業務ロジックを使用して有効な商品データをフィルタリング
      if (filterValidProductData) {
        filtered = filterValidProductData(filtered);
      }

      if (keyword) {
        filtered = filtered.filter(product => 
          product.商品名.includes(keyword) || product.商品コード.includes(keyword)
        );
      }

      if (category) {
        filtered = filtered.filter(product => 
          product.商品名.includes(category)
        );
      }

      currentProducts = filtered;
      renderCalculationTable();
    } catch (error) {
      showError('商品検索に失敗しました');
    }
  }

  // 需要予測更新
  async function updateForecast() {
    if (!validateInputs()) return;

    try {
      const storeId = container.querySelector('#select-store').value;
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;

      // 売上データ収集
      const salesData = collectSalesData ? 
        await collectSalesData(storeId, startDate, endDate) : 
        await window.aivicApi.list(4); // 売上実績

      if (!salesData || salesData.length === 0) {
        showError('対象期間の売上データが見つかりません');
        return;
      }

      // 商品別売上データ分類
      const productSalesData = classifySalesDataByProduct ? 
        classifySalesDataByProduct(salesData) : 
        salesData;

      // 天候データ収集
      const weatherData = collectWeatherData ? 
        await collectWeatherData(startDate, endDate) : 
        [];

      // イベントデータ収集
      const eventData = collectEventData ? 
        await collectEventData(startDate, endDate) : 
        [];

      // 季節データ収集
      const seasonalData = collectSeasonalData ? 
        collectSeasonalData(startDate, endDate) : 
        {};

      // 相関分析実行
      const correlations = {};
      if (analyzeCorrelationSalesWeather && weatherData.length > 0) {
        correlations.weather = analyzeCorrelationSalesWeather(productSalesData, weatherData);
      }
      if (analyzeCorrelationSalesEvent && eventData.length > 0) {
        correlations.event = analyzeCorrelationSalesEvent(productSalesData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlations.seasonal = analyzeCorrelationSalesSeason(productSalesData, seasonalData);
      }

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData ? 
        await compareWithHistoricalData(productSalesData, startDate, endDate) : 
        null;

      // 予測結果を格納
      currentForecast = {
        salesData: productSalesData,
        correlations,
        historicalComparison,
        period: { startDate, endDate },
        storeId
      };

      renderCalculationTable();
      showSuccess('需要予測を更新しました');

    } catch (error) {
      console.error('需要予測更新エラー:', error);
      showError('需要予測の更新に失敗しました');
    }
  }

  // 発注量計算
  async function calculateOrderQuantity() {
    if (!validateInputs()) return;
    if (currentProducts.length === 0) {
      showError('商品データがありません。まず商品を検索してください');
      return;
    }

    try {
      const rows = container.querySelectorAll('#calculation-table tbody tr');
      const calculations = [];

      for (const row of rows) {
        const productId = row.dataset.productId;
        const adjustmentInput = row.querySelector('.adjustment-input');
        const adjustment = parseFloat(adjustmentInput?.value || 0);

        if (!validateNumber(adjustment, '調整値', -100, 100)) {
          return;
        }

        const product = currentProducts.find(p => p.商品ID == productId);
        if (!product) continue;

        // 基本予測値の計算（相関分析結果を使用）
        let baseForecast = 0;
        if (currentForecast.salesData && currentForecast.salesData[productId]) {
          baseForecast = currentForecast.salesData[productId].averageSales || 0;
        }

        // 調整値適用
        const adjustedForecast = baseForecast * (1 + adjustment / 100);

        // 安全在庫を考慮した発注量計算
        const safetyStock = product.安全在庫数 || 0;
        const currentStock = product.現在在庫数 || 0;
        const orderQuantity = Math.max(0, adjustedForecast + safetyStock - currentStock);

        calculations.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: Math.round(adjustedForecast),
          発注量: Math.round(orderQuantity),
          調整値: adjustment,
          計算日時: new Date().toISOString()
        });

        // テーブル行の更新
        const forecastCell = row.querySelector('.forecast-quantity');
        const orderCell = row.querySelector('.order-quantity');
        if (forecastCell) forecastCell.textContent = Math.round(adjustedForecast);
        if (orderCell) orderCell.textContent = Math.round(orderQuantity);
      }

      // 計算結果を保存
      if (calculations.length > 0) {
        await window.aivicApi.save(6, calculations); // 発注計算結果
        showSuccess(`${calculations.length}件の発注量を計算しました`);
      }

    } catch (error) {
      console.error('発注量計算エラー:', error);
      showError('発注量の計算に失敗しました');
    }
  }

  // 計算テーブル描画
  function renderCalculationTable() {
    const tbody = container.querySelector('#calculation-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    currentProducts.forEach(product => {
      const row = document.createElement('tr');
      row.dataset.productId = product.商品ID;

      // 予測値の取得
      let forecastValue = 0;
      if (currentForecast.salesData && currentForecast.salesData[product.商品ID]) {
        forecastValue = currentForecast.salesData[product.商品ID].averageSales || 0;
      }

      row.innerHTML = `
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${product.現在在庫数 || 0}</td>
        <td class="forecast-quantity">${Math.round(forecastValue)}</td>
        <td><input type="number" class="adjustment-input" value="0" min="-100" max="100" step="1"></td>
        <td class="order-quantity">-</td>
      `;

      tbody.appendChild(row);
    });
  }

  // 発注データ保存
  async function saveOrderData() {
    try {
      const rows = container.querySelectorAll('#calculation-table tbody tr');
      const orderData = [];

      for (const row of rows) {
        const productId = row.dataset.productId;
        const orderQuantity = parseInt(row.querySelector('.order-quantity')?.textContent || 0);

        if (orderQuantity > 0) {
          const product = currentProducts.find(p => p.商品ID == productId);
          orderData.push({
            店舗ID: container.querySelector('#select-store').value,
            商品ID: productId,
            商品コード: product.商品コード,
            発注数量: orderQuantity,
            発注日: new Date().toISOString().split('T')[0],
            ステータス: '計算済み'
          });
        }
      }

      if (orderData.length === 0) {
        showError('保存する発注データがありません');
        return;
      }

      await window.aivicApi.save(5, orderData); // 発注管理
      showSuccess(`${orderData.length}件の発注データを保存しました`);

    } catch (error) {
      console.error('発注データ保存エラー:', error);
      showError('発注データの保存に失敗しました');
    }
  }

  // イベントハンドラーの設定
  function setupEventHandlers() {
    // 商品検索ボタン
    const searchBtn = container.querySelector('#btn-search-products');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 需要予測更新ボタン
    const updateBtn = container.querySelector('#btn-update-forecast');
    if (updateBtn) {
      updateBtn.addEventListener('click', updateForecast);
    }

    // 発注量計算ボタン
    const calculateBtn = container.querySelector('#btn-calculate-order');
    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateOrderQuantity);
    }

    // 発注データ保存ボタン
    const saveBtn = container.querySelector('#btn-save-order');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // 検索フィールドでのEnterキー
    const searchInput = container.querySelector('#input-search');
    if (searchInput) {
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
          searchProducts();
        }
      });
    }

    // 店舗選択変更時
    const storeSelect = container.querySelector('#select-store');
    if (storeSelect) {
      storeSelect.addEventListener('change', () => {
        currentForecast = {};
        renderCalculationTable();
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      setupEventHandlers();

      // デフォルト日付設定
      const today = new Date();
      const startDate = new Date(today.getFullYear(), today.getMonth() - 1, 1);
      const endDate = new Date(today.getFullYear(), today.getMonth(), 0);

      const startInput = container.querySelector('#input-start-date');
      const endInput = container.querySelector('#input-end-date');

      if (startInput) startInput.value = startDate.toISOString().split('T')[0];
      if (endInput) endInput.value = endDate.toISOString().split('T')[0];

    } catch (error) {
      console.error('初期化エラー:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
